package com.muxigame.city;
import java.util.*;
import net.minecraft.gametest.framework.*;
import net.neoforged.neoforge.gametest.*;

@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false)
public class CityTestsWorkMaterials {
 @GameTest(template="empty") public static void equipmentCatalogIsEmptyBoundedAndKeepsCustomSettings(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){
  CityMaterialCatalog.ensure(f.s,f.city);h.assertTrue(!f.city.housing.market.containsKey("city_settlements:rural_stove"),"Unconfigured towns do not receive a new material system");CityTestsModel.configure(f);for(var c:List.of(f.city,f.village))for(String id:CityMaterialCatalog.EQUIPMENT.keySet()){var m=c.housing.market.get(id);h.assertTrue(m!=null&&m.stock==0&&m.cap==8&&m.supply==1&&m.supplier!=null,"Catalog adds an empty quote owned by a real local vendor");}var m=f.city.housing.market.get("city_settlements:rural_stove");m.priceCents=777;m.stock=3;m.supply=0;CityMaterialCatalog.ensure(f.s,f.city);h.assertTrue(m.priceCents==777&&m.stock==3&&m.supply==0,"Resume cannot overwrite the administrator's existing price, supply or stock");
 }h.succeed();}
 @GameTest(template="empty") public static void productionMaterialsUseExistingDeclaredSupplyAndNeverFood(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){
  CityTestsModel.configure(f);var st=f.city.housing;var food=new CityHousing.Material();food.stock=0;food.supply=100;st.market.put("minecraft:bread",food);long cash=f.t.money(f.s);CityHousing.advanceSupply(st,1200);for(String id:CityMaterialCatalog.EQUIPMENT.keySet()){var m=st.market.get(id);h.assertTrue(m.stock==1&&m.supplied==1,"One recorded material unit per configured supply period");}CityHousing.advanceSupply(st,24000);h.assertTrue(st.market.get("city_settlements:rural_stove").stock==8&&food.stock==0&&f.t.money(f.s)==cash,"Bounded construction supply never adds food or currency");
 }h.succeed();}
 @GameTest(template="empty",timeoutTicks=200) public static void allDestroyedModeledWorkpointsRecoverFromPurchasedCatalogSupply(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){
  CityTestsModel.configure(f);for(var c:List.of(f.city,f.village))for(var entry:c.housing.houses.entrySet())if(CityWorks.workshop(c,entry.getKey()))entry.getValue().damaged.addAll(entry.getValue().baseline.keySet());var initial=CityTestsLongRun.materialScore(f);f.run(5);var finalScore=CityTestsLongRun.materialScore(f);h.assertTrue(finalScore.entrySet().stream().allMatch(e->e.getValue().equals(initial.get(e.getKey()))),"Every supplied, purchased, converted and consumed production material balances");h.assertTrue(f.conserved&&f.r.state.people.values().stream().noneMatch(p->p.dead),"Recovery adds no money or food and keeps the independent population alive");h.assertTrue(java.util.stream.Stream.of(f.city,f.village).allMatch(c->c.housing.houses.entrySet().stream().filter(e->CityWorks.workshop(c,e.getKey())).allMatch(e->e.getValue().damaged.isEmpty())),"All95 old workpoints recover through ordinary maintenance, without injecting95 finished workpoints or calling the risk helper");
 }h.succeed();}
 @GameTest(template="empty") public static void unavailableCityRegistryCannotEraseFarmRegistration(GameTestHelper h){try(var f=new CityTestsNumeric.NumericFixture(h)){var original=f.maintenance.state.cities.get(f.village.id);h.assertTrue(original!=null&&!original.baseline.isEmpty(),"Fixture contains registered farmland");var workers=new LinkedHashMap<>(f.maintenance.state.workers);CityData.get(f.server).cities.remove(f.village.id);for(int i=0;i<8;i++)CityMaintenance.tick(f.server);h.assertTrue(f.maintenance.state.cities.get(f.village.id)==original&&f.maintenance.state.workers.equals(workers),"A failed or unavailable city registry cannot silently delete farm/work definitions");var saved=f.maintenance.save(new net.minecraft.nbt.CompoundTag(),h.getLevel().registryAccess());var loaded=CityMaintenance.load(saved,h.getLevel().registryAccess());h.assertTrue(loaded.state.cities.get(f.village.id).baseline.equals(original.baseline),"Preserved plans pass strict save/reload without adding harvest or wages");}h.succeed();}
 @GameTest(template="empty") public static void actualSavedDataFallbackCannotOverwriteUnreadableExistingFile(GameTestHelper h){var s=h.getLevel().getServer();String id="city_guard_test_"+UUID.randomUUID().toString().replace("-","");var file=s.getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("data").resolve(id+".dat");byte[] broken={1,2,3,4};try{java.nio.file.Files.createDirectories(file.getParent());java.nio.file.Files.write(file,broken);boolean refused=false;try{s.overworld().getDataStorage().computeIfAbsent(new net.minecraft.world.level.saveddata.SavedData.Factory<>(()->CitySaveSafety.newData(s,id,CityData::new),CityData::load),id);}catch(IllegalStateException expected){refused=true;}h.assertTrue(refused&&Arrays.equals(java.nio.file.Files.readAllBytes(file),broken),"The actual SavedData fallback refuses an existing unreadable file without replacing it with an empty city");String absent=id+"_new";h.assertTrue(s.overworld().getDataStorage().computeIfAbsent(new net.minecraft.world.level.saveddata.SavedData.Factory<>(()->CitySaveSafety.newData(s,absent,CityData::new),CityData::load),absent)!=null,"A genuinely new world may still create its first empty registry");}catch(java.io.IOException ex){throw new IllegalStateException(ex);}finally{try{java.nio.file.Files.deleteIfExists(file);}catch(java.io.IOException ex){throw new IllegalStateException(ex);}}h.succeed();}
}
